 "판정 모델이 없어서 자동으로 고르지 못해요": "没有判定模型，无法自动选择",
 "판정 모델 정하기": "设置判定模型",
 "꺼져 있어요. 모든 요청이 기본 모델로 가요.": "已关闭。所有请求都会发往默认模型。",
 "켜져 있지만 판정 모델이 없어요.": "已开启，但没有判定模型。",
 "기본 모델 (자동 라우팅을 껐거나 판정 모델이 고르지 못할 때)": "默认模型（自动路由关闭，或判定模型无法选择时）",
 "고른 모델이 답을 시작하기 전에 거절되면 바로 다음 모델로 넘겨요. 답을 쓰던 중에 끊긴 요청은 넘기지 않아요.": "如果所选模型在开始回答前就拒绝了，请求会立刻转给下一个模型。回答到一半中断的请求不会转移。",
 "1번 모델부터 차례로": "从 1 号模型开始依次尝试",
 "한도나 크레딧이 떨어져 거절된 모델은 잠시 쉬며 맨 뒤로 가요. 요청 하나로 먼저 확인한 뒤 돌아와요.": "因达到限额或额度用完而被拒绝的模型会先暂停一会儿，并排到最后。用一次请求先确认后再回来。",
 "실패가 이보다 잦으면 라우팅 현황에 '주의' 표시": "失败比这更频繁时，在路由状况中显示“注意”",
 "느릴 때 응답 시간이 이보다 길면 '느림' 표시": "较慢时的响应时间比这更长时，显示“较慢”",
 "자세히 · 넘기는 순서와 표시 기준": "更多 · 转移顺序和显示标准",
 "넘기는 설정을 바꿨어요. 저장해야 적용돼요.": "你更改了转移设置。保存后才会生效。",
 "이런 일은 늘 이 모델로": "这类任务始终用这个模型",
 "넘기는 설정 저장": "保存转移设置",
 "요청에 든 낱말로 일의 종류를 알아보고, 정한 모델로 바로 보내요. 판정 모델보다 먼저 쓰고, 자동 라우팅이 켜져 있을 때만 써요.": "根据请求中的词语判断任务类型，并直接发给指定的模型。优先于判定模型使用，且仅在自动路由开启时使用。",
 "판정 모델에 맡기기": "交给判定模型",
