 "자동 라우팅을 껐어요. 모든 요청이 기본 모델로 가요.": "自动路由已关闭。所有请求都会发往默认模型。",
 "켠 모델이 없어요. 설정 › 에이전트에서 모델을 켜면 여기에 나와요.": "没有已开启的模型。在 设置 › 代理 中开启模型后，会显示在这里。",
 "저장 안 함": "未保存",
