 "이럴 때 보내요": "符合这些情况时发送",
 "1번 모델이 기본으로 가고, 실패하면 다음 번호로 넘겨요.": "1 号模型为默认，失败时转给下一个编号。",
 "자세히 · 한도": "更多 · 限额",
 "한도를 넘으면 그룹에서는 다음 모델로 넘기고, 아니면 잠깐 뒤에 다시 하라고 알려요. 비우거나 0이면 제한이 없어요.": "超出限额时，组内会转给下一个模型；否则会通知稍后重试。留空或为 0 表示不限制。",
 "이 모델을 바꿨어요. 저장해야 적용돼요.": "你更改了这个模型。保存后才会生效。",
 "판정 모델이 고르지 않아 1번 모델로": "判定模型未选择，所以用 1 号模型",
 "기본 모델로": "默认模型",
 "자세히 · 모델 묶음": "更多 · 模型组",
 "관련 교훈을 찾아 고를 관측을 선택하고, 평가 과제 파일을 넣어 주세요.": "请查找相关经验，选择要使用的观察记录，并添加评估任务文件。",
 "교훈을 읽지 못했어요. 권한과 서버 버전을 확인해 주세요.": "无法读取经验。请检查权限和服务器版本。",
 "평가 과제는 데스크톱 앱이 평가 서버에서 불러와요. 데스크톱 앱에서 열어 주세요.": "评估任务由桌面应用从评估服务器加载。请在桌面应用中打开。",
 "평가 서버가 평가 설정을 보내지 않았어요. 평가 서버의 Arkism 설정을 확인해 주세요.": "评估服务器没有发送评估设置。请检查评估服务器上的 Arkism 设置。",
 "평가 서버에 등록된 평가 과제가 없어요. 평가 서버 설정에 과제를 하나 등록하면 자동으로 채워져요.": "评估服务器上没有已登记的评估任务。在评估服务器设置中登记一个任务后，会自动填入。",
 "평가 서버의 Arkism이 오래돼 통과 기준을 주지 않아요. 평가 서버를 업데이트하면 자동으로 채워져요.": "评估服务器上的 Arkism 版本过旧，没有提供通过标准。更新评估服务器后会自动填入。",
 "아직 개선안을 만들 수 없어요.": "暂时还无法生成改进方案。",
 "쓸 관측 (빼려면 체크 해제)": "要使用的观察记录（不想用请取消勾选）",
 "필요한 점수 향상 (100점 만점)": "所需提升的分数（满分 100）",
 "후보 실행 시간 상한 (분)": "候选运行时间上限（分钟）",
 "비용 상한 (평가기가 보고하는 값, 비우면 제한 없음)": "费用上限（评估器报告的值，留空则不限制）",
 "고급 설정": "高级设置",
 "비용 제한 없음": "不限制费用",
 "고급 설정의 값을 확인해 주세요.": "请检查高级设置中的值。",
 "평가 과제": "评估任务",
 "개선안 만들기": "生成改进方案",
 "고른 관측과 지금 스킬이 모델에 전달되며 생성 비용이 들어요. 만든 뒤 비교 평가·승인을 거쳐야 적용돼요.": "所选的观察记录和当前技能会发送给模型，生成时会产生费用。生成后需经过对比评估和批准才会生效。",
 "관측을 3~16개 골라 주세요.": "请选择 3~16 条观察记录。",
 "만들기를 시작하지 못했어요. 스킬이 그사이 바뀌었거나 앱 저장 공간에 문제가 있어요. 다시 열어 주세요.": "无法开始生成。技能可能在此期间发生了变化，或应用的存储空间出了问题。请重新打开。",
 "서버 (이전 버전)": "服务器（旧版本）",
 "앱보다 오래됨": "比应用旧",
 "이 PC 내장 서버는 앱과 함께 업데이트돼요. 앱을 업데이트한 뒤 다시 연결하세요.": "本机内置服务器会随应用一起更新。请先更新应用，然后重新连接。",
 "서버 주소로 연결하면 앱에서 서버를 업데이트할 수 없어요. 서버에서 직접 업데이트해 주세요.": "通过服务器地址连接时，无法在应用中更新服务器。请直接在服务器上更新。",
 "업데이트 보기": "查看更新",
 "업데이트할 수 없음": "无法更新",
 "앱": "应用",
 "이 앱은 업데이트 주소 없이 빌드돼 서버 묶음을 받을 수 없어요.": "此应用构建时没有更新地址，无法获取服务器安装包。",
 "이 앱 버전에 맞는 서버 묶음이 릴리스에 없어요.": "发布版本中没有适用于此应用版本的服务器安装包。",
 "서버의 CPU 종류(아키텍처)용 묶음이 없어요. Linux x86_64·arm64만 지원해요.": "没有适用于服务器 CPU 类型（架构）的安装包。仅支持 Linux x86_64 和 arm64。",
 "내려받은 서버 묶음의 서명이 맞지 않아 설치하지 않았어요.": "下载的服务器安装包签名不匹配，因此未安装。",
 "릴리스에서 서버 묶음을 받지 못했어요. 인터넷 연결을 확인하세요.": "无法从发布版本下载服务器安装包。请检查网络连接。",
 "서버에서 Arkism 설치 폴더를 찾지 못했어요.": "在服务器上找不到 Arkism 安装文件夹。",
 "설치 폴더에 쓸 권한이 없어요. 서버에서 이 SSH 사용자에게 폴더 쓰기 권한을 주거나, 비밀번호 없는 sudo(sudo -n)를 허용해 주세요.": "没有写入安装文件夹的权限。请在服务器上为此 SSH 用户授予该文件夹的写入权限，或允许免密码 sudo（sudo -n）。",
 "서비스를 다시 시작하려면 sudo가 필요해요. 이 SSH 사용자에게 비밀번호 없는 sudo(sudo -n)를 허용하거나, 서버에서 직접 업데이트해 주세요.": "重启服务需要 sudo。请为此 SSH 用户允许免密码 sudo（sudo -n），或直接在服务器上更新。",
 "Arkism 서버를 돌리는 systemd 서비스를 찾지 못했어요. 서버를 서비스로 띄운 뒤 다시 시도하거나, 직접 업데이트해 주세요.": "找不到运行 Arkism 服务器的 systemd 服务。请先将服务器作为服务启动后再试，或直接更新。",
 "서버 묶음 안의 파일이 예상과 달라 설치하지 않았어요.": "服务器安装包中的文件与预期不符，因此未安装。",
 "새 서버가 정상으로 뜨지 않아 예전 버전으로 되돌렸어요. DB 구조 변경이 필요하면 서버에서 memoryd --init-db를 먼저 실행하세요.": "新服务器未能正常启动，已恢复到旧版本。如果需要更改数据库结构，请先在服务器上运行 memoryd --init-db。",
 "새 서버가 뜨지 않았고 되돌리기도 실패했어요. 서버의 설치 폴더 .backup-* 에서 직접 되돌려 주세요.": "新服务器未能启动，恢复也失败了。请在服务器安装文件夹的 .backup-* 中手动恢复。",
