 "Codex 설정에 이미 arkism 공급자가 있어요. 직접 지운 뒤 다시 해 주세요.": "Codex 设置中已有 arkism 提供方。请先手动删除,然后再试一次。",
 "에이전트 설정 파일을 읽지 못했어요.": "无法读取智能体的设置文件。",
 "연결하지 못했어요.": "无法连接。",
 "이미 연결하는 중이에요.": "正在连接中。",
 "이 PC에서 찾지 못했어요.": "在这台电脑上没有找到。",
 "연결한 에이전트는 이 PC의 Arkism 중계기로 요청을 보내고, 설정 › 에이전트에서 켠 모델 중에서 자동으로 골라 답해요. 각자 로그인은 그대로 써요.": "已连接的智能体会把请求发送到这台电脑上的 Arkism 中继器,并从你在 设置 › 智能体 中开启的模型里自动挑选来回答。各自的登录状态保持不变。",
 "기본 모델이 ‘자동’이 돼요. /model에서 다른 모델도 고를 수 있어요.": "默认模型会变为“自动”。你也可以在 /model 中选择其他模型。",
 "~/.codex/config.toml에 Arkism 공급자를 넣고 모델을 ‘자동’으로 바꿔요.": "会在 ~/.codex/config.toml 中添加 Arkism 提供方,并把模型改为“自动”。",
 "API 키로 로그인한 Gemini CLI만 돼요. Google 로그인은 주소 설정을 무시해요.": "仅适用于用 API 密钥登录的 Gemini CLI。使用 Google 登录时会忽略地址设置。",
