 "내 모델로 판별하려면 주소와 모델 이름이 필요해요.": "要用自己的模型来判别,需要填写地址和模型名称。",
 "주소는 https이거나 이 PC(127.0.0.1)여야 해요.": "地址必须是 https 或这台电脑(127.0.0.1)。",
