 "Arkism 내장 검사(비밀값·원격 실행·삭제 명령·자격 파일·유출·프롬프트 주입, SKILL.md 구성)가 서버의 스킬 폴더를 검사한 결과예요.": "这是 Arkism 内置检查(密钥、远程执行、删除命令、凭据文件、泄露、提示词注入、SKILL.md 结构)对服务器上技能文件夹的检查结果。",
