 "저장소 밖 폴더 (공용 기억만)": "仓库之外的文件夹(仅共用记忆)",
 "저장소에 작업 계약 파일이 있으면 관련 기억(최대 6개)이 따로 붙고, 그만큼 목차 자리가 줄어요. 계약 파일은 그 PC에서만 읽을 수 있어 여기선 빠져요.": "如果仓库中有任务契约文件,会另外附上相关记忆(最多 6 条),目录的空间也会相应减少。契约文件只有那台电脑才能读取,所以这里不包含。",
