 "오늘 이후 날짜를 고르세요.": "请选择今天之后的日期。",
 "만료일 지우기": "清除到期日",
 "개인정보 지우기": "删除个人信息",
 "이 기억과 근거가 된 원본 기록을 영구히 지워요. 같은 원본에서 나온 다른 기억도 함께 지워져요.": "会永久删除这条记忆及其依据的原始记录。来自同一原始记录的其他记忆也会一并删除。",
 "영구 삭제": "永久删除",
 "사람 이름이나 메일 주소처럼 지우고 싶은 말을 넣으면, 그 말이 들어간 기억과 원본 기록을 모두 찾아 영구히 지워요. 먼저 몇 개인지 보여 드려요.": "输入你想删除的内容,比如人名或邮箱地址。Arkism 会找出包含它的所有记忆和原始记录并永久删除。会先告诉你有多少条。",
 "지울 말 (이름·메일 주소 등)": "要删除的内容(姓名、邮箱地址等)",
 "예: 홍길동, name@example.com": "例如:张三、name@example.com",
 "너무 많아 일부만 셌어요. 지운 뒤 다시 찾아보세요.": "数量太多,只统计了一部分。删除后请再查找一次。",
