 "두 글자 이상 입력하세요.": "请至少输入两个字符。",
 "이 계정은 기억과 원본 기록을 찾을 수 없어요.": "这个账号无法查找记忆和原始记录。",
 "찾지 못했어요. 연결을 확인하고 다시 시도하세요.": "查找失败。请检查连接后再试。",
 "입력한 말이 달라 지우지 않았어요.": "输入的内容不一致,所以没有删除。",
