 "다른 서버에 연결": "连接到其他服务器",
 "서버 연결은 Arkism 앱에서만 돼요.": "只有在 Arkism 应用中才能连接服务器。",
 "접속 토큰": "访问令牌",
 "서버 관리자에게 받은 Arkism 접속 토큰. 이 탭을 닫으면 지워져요": "从服务器管理员那里获得的 Arkism 访问令牌。关闭此标签页后会被清除",
 "자세히 (워크스페이스·프로젝트)": "详细设置(工作区 · 项目)",
