 "Arkism 서버에 로그인": "登录 Arkism 服务器",
 "서버 관리자에게 받은 접속 토큰을 붙여 넣으세요. 토큰은 이 브라우저 탭에만 두고, 탭을 닫으면 지워져요.": "请粘贴从服务器管理员那里获得的访问令牌。令牌只保存在这个浏览器标签页中,关闭标签页后会被清除。",
 "주소를 확인하세요. user@서버주소 또는 user@서버주소:포트 처럼 적어요.": "请检查地址。请写成 user@服务器地址 或 user@服务器地址:端口 的形式。",
 "이 PC에서 ssh 프로그램을 찾지 못했어요. OpenSSH(또는 Git for Windows)를 설치해 주세요.": "在这台电脑上找不到 ssh 程序。请安装 OpenSSH(或 Git for Windows)。",
 "SSH 로그인이 거부됐어요. 이 PC에서 ‘ssh 주소’가 비밀번호 없이(SSH 키로) 되는지 확인하세요.": "SSH 登录被拒绝。请确认在这台电脑上“ssh 地址”无需密码(使用 SSH 密钥)即可登录。",
 "서버에 닿지 못했어요. 주소·포트와 네트워크 연결을 확인하세요.": "无法连接到服务器。请检查地址、端口和网络连接。",
 "서버에 로그인은 됐지만 Arkism이 설치돼 있지 않아요.": "已登录服务器,但那里没有安装 Arkism。",
 "서버의 Arkism이 오래돼서 이 연결 방식을 몰라요. 서버의 Arkism을 업데이트해 주세요.": "服务器上的 Arkism 版本太旧,不支持这种连接方式。请更新服务器上的 Arkism。",
