 "서버의 Git·스킬 화면은 이 연결로 돼요. 에이전트의 기억 수집은 SSH 키가 있어야 서버로 가요.": "服务器的 Git 和技能页面通过这个连接工作。智能体的记忆收集只有在有 SSH 密钥时才能发送到服务器。",
