 "SSH 키 또는 비밀번호로 접속해요. 비밀번호는 이 PC의 키체인에 저장해 다시 묻지 않고, 연결 끊기를 누르면 지금 연결된 서버의 비밀번호를 지워요.": "使用 SSH 密钥或密码登录。密码会保存到这台电脑的钥匙串中，之后不会再询问；点击断开连接会删除当前服务器的密码。",
