 "합치기 제안 · AI 제안": "合并建议 · AI 建议",
 "지운 기억이에요. 에이전트는 쓰지 않아요. 되살리면 지우기 전처럼 다시 써요.": "这是已删除的记忆。代理不会使用它。恢复后，会像删除前一样继续使用。",
 "지웠어요. 「지운 기억」에서 언제든 되살릴 수 있어요.": "已删除。你随时可以在“已删除的记忆”中恢复。",
 "예전 방식으로 저장돼 사람이 승인한 기록이 남지 않은 기억이에요. 할 일은 없고, 내용도 바꾸지 않아요.": "这些记忆是以旧方式保存的，没有留下人工批准的记录。无需处理，内容也不会改动。",
 "지운 기억": "已删除的记忆",
