 "아직 기억이 없어요. AI와 대화하면 기억할 만한 내용이 「확인해 주세요」에 올라와요. 직접 적어 둘 수도 있어요.": "还没有记忆。和 AI 对话时，值得记住的内容会出现在“请确认”中。你也可以自己写下来。",
 "지운 기억이 없어요.": "没有已删除的记忆。",
 "되살렸어요. 에이전트가 다시 써요.": "已恢复。代理会再次使用它。",
 "이 계정은 기억을 되살릴 수 없어요.": "此账号无法恢复记忆。",
